<template>
  <div class="assistant">
    <h2>眼科智能助手</h2>
    <div class="chat-container">
      <div class="chat-messages">
        <div v-for="(message, index) in messages" :key="index" class="message">
          <div :class="['message-content', message.sender === 'user' ? 'user' : 'assistant']">
            {{ message.content }}
          </div>
        </div>
      </div>
      <div class="chat-input">
        <input type="text" v-model="userInput" @keyup.enter="sendMessage" placeholder="输入您的问题...">
        <button @click="sendMessage">发送</button>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: 'AssistantView',
  data() {
    return {
      messages: [],
      userInput: ''
    };
  },
  methods: {
    async sendMessage() {
      if (!this.userInput.trim()) return;

      const userMessage = {
        sender: 'user',
        content: this.userInput
      };
      this.messages.push(userMessage);

      try {
        // 调用 getAnswer API
        const response = await fetch('http://localhost:3000/api/assistant', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({ question: this.userInput })
        });
        const data = await response.json();
        const assistantMessage = {
          sender: 'assistant',
          content: data.answer
        };
        this.messages.push(assistantMessage);
      } catch (error) {
        console.error('Error sending message:', error);
        const assistantMessage = {
          sender: 'assistant',
          content: '抱歉，我无法回答您的问题，请稍后再试。'
        };
        this.messages.push(assistantMessage);
      }

      this.userInput = '';
    },
  }
};
</script>

<style scoped>
@import '@/assets/css/global.css';
@import '@/assets/css/header.css';
@import '@/assets/css/assistant.css';
  </style>